import React, { useState, useEffect } from "react";
import axios from "axios";

function ProductsPage() {
  const [products, setProducts] = useState([]);  // Initialize as an empty array
  const [error, setError] = useState(null);

  useEffect(() => {
    axios
      .get("http://localhost:5000/products")  // Fetch products from the backend
      .then((response) => {
        setProducts(response.data);  // Ensure the response data is an array
      })
      .catch((error) => {
        setError("Error fetching products");
        console.error("Error fetching products:", error);
      });
  }, []);

  return (
    <div>
      <h1>Products</h1>
      {error && <p>{error}</p>}
      <ul>
        {Array.isArray(products) && products.length > 0 ? (
          products.map((product) => (
            <li key={product.product_id}>{product.name}</li>
          ))
        ) : (
          <p>No products available or loading...</p>
        )}
      </ul>
    </div>
  );
}

export default ProductsPage;
